    10	    // The OldDot mobile app does not URL encode the parameters, but OldDot web
    11	    // does. We don't want to deploy OldDot mobile again, so as a work around we
    12	    // compare the session email to both the decoded and raw email from the transition link.
    13	    const params = new URLSearchParams(transitionURL);
    14	    const paramsEmail = params.get('email');
    15	
    16	    // If the email param matches what is stored in the session then we are
    17	    // definitely not logging in as a new user
