    23	    // Capture the un-encoded text in the email param
    24	    const emailParamRegex = /[?&]email=([^&]*)/g;
    25	    const matches = emailParamRegex.exec(transitionURL ?? '');
    26	    const linkedEmail = matches?.[1] ?? null;
    27	    return linkedEmail !== sessionEmail;
